export interface KnowledgeFAQ {
  question: string;
  answer: string;
}

// Structured content blocks — the new, richer alternative to the flat
// `body` string. Paragraph/list/FAQ text may contain **bold** and
// [link text](/path) inline markup, parsed by renderInlineText in
// KnowledgeArticlePage.tsx. Deliberately minimal (three block types)
// rather than a full markdown implementation — this is meant to be a
// straightforward shape to migrate into Sanity later, not a rendering
// engine in its own right.
export type KnowledgeContentBlock =
  | { type: 'heading'; level: 2 | 3; text: string }
  | { type: 'paragraph'; text: string }
  | { type: 'list'; items: string[] };

export interface KnowledgeArticle {
  id: number;
  slug: string;
  category: string;
  title: string;
  summary: string;
  readTime: string;
  level: string;
  /** Legacy flat format — still used by the original 21 articles. */
  body?: string;
  /** New structured format — used by articles with real heading/list/FAQ structure. */
  sections?: KnowledgeContentBlock[];
  faqs?: KnowledgeFAQ[];
  sources?: string[];
  author?: string;
  reviewer?: string;
  publishedDate?: string;
  lastReviewedDate?: string;
}

